<?php
require_once __DIR__.'/includes/bootstrap.php';require_once __DIR__.'/includes/commerce.php';require_once __DIR__.'/includes/invoices.php';require_once __DIR__.'/includes/simple_pdf.php';
$pdo=db();$token=(string)($_GET['token']??'');$order=$pdo&&commerce_schema_ready($pdo)?commerce_order_by_token($pdo,$token):null;$invoice=$order?invoice_for_order($pdo,(int)$order['id']):null;if(!$order||!$invoice){http_response_code(404);exit('Invoice unavailable.');}
